const reqPerSec = 1000;
const kbPerLog = 1;
const errorRate = 0.02;
const pricePerGB = 0.10;
const secsPerMonth = 30 * 24 * 3600;

// bytes -> GB helper
function gb(bytes) { return bytes / (1024 ** 3); }

// TODO: rawBytes = every request logged at full size for a month
const rawBytes = reqPerSec * kbPerLog * 1024 * secsPerMonth;

// TODO: sampled = keep 100% of error lines + 1/10 of the success lines
const errBytes = rawBytes * errorRate;
const sampledSuccess = rawBytes * (1 - errorRate) / 10;
const sampledBytes = errBytes + sampledSuccess;

console.log('raw    GB/month:', gb(rawBytes).toFixed(0), '$', (gb(rawBytes) * pricePerGB).toFixed(0));
console.log('sampled GB/month:', gb(sampledBytes).toFixed(1), '$', (gb(sampledBytes) * pricePerGB).toFixed(0));
console.log('cut:', (100 * (1 - sampledBytes / rawBytes)).toFixed(0) + '%');
